package com.careerpilot.backend.modules.discovery.services;
import com.careerpilot.connector.sdk.DiscoveredJob; import com.careerpilot.backend.modules.discovery.repositories.DiscoveryJobRepository; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*;
@Service public class DuplicateDetector { private final DiscoveryJobRepository repo; public DuplicateDetector(DiscoveryJobRepository r){repo=r;} public String hash(DiscoveredJob j){String canonical=String.join("|",safe(j.getSource()),safe(j.getNormalizedCompany()),safe(j.getNormalizedTitle()),safe(j.getLocation()),safe(j.getRawContent()));try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} public boolean duplicate(DiscoveredJob j){return repo.findByConnectorIdAndExternalId(j.getConnectorId(),j.getExternalId()).isPresent()||repo.findFirstBySourceAndNormalizedCompanyAndNormalizedTitleAndLocationAndContentHash(j.getSource(),j.getNormalizedCompany(),j.getNormalizedTitle(),j.getLocation(),j.getContentHash()).isPresent();} private String safe(String s){return s==null?"":s.strip().toLowerCase(Locale.ROOT);} }
